import openpyxl
wb = openpyxl.load_workbook('data/workbook.xlsx')
print('Sheet names:', wb.sheetnames)

ts = wb['Task']
print('\n=== Task sheet layout ===')
for row in ts.iter_rows(min_row=1, max_row=55, max_col=13, values_only=False):
    vals = [(c.coordinate, c.value) for c in row if c.value is not None]
    if vals:
        print(vals)

ds = wb['Data']
print('\n=== Data sheet rows 1-5 (headers) ===')
for row in ds.iter_rows(min_row=1, max_row=5, max_col=20, values_only=False):
    vals = [(c.coordinate, c.value) for c in row if c.value is not None]
    if vals:
        print(vals)

print('\n=== Data sheet rows 18-40 ===')
for row in ds.iter_rows(min_row=18, max_row=40, max_col=20, values_only=False):
    vals = [(c.coordinate, c.value) for c in row if c.value is not None]
    if vals:
        print(vals)

print('\n=== Data sheet row 21 header check ===')
for c in ds[21]:
    if c.value is not None:
        print(c.coordinate, repr(c.value))

print('\n=== Task D column (series codes) ===')
for r in range(10, 45):
    v = ts.cell(r, 4).value
    if v is not None:
        print(f'D{r}:', repr(v))

print('\n=== Task row 10 (years) ===')
for c in range(1, 14):
    v = ts.cell(10, c).value
    if v is not None:
        print(f'{ts.cell(10,c).coordinate}:', repr(v))

print('\n=== Task labels col A-G rows 10-50 ===')
for r in range(10, 52):
    for c in range(1, 8):
        v = ts.cell(r, c).value
        if v is not None:
            print(f'{ts.cell(r,c).coordinate}:', repr(v))
